/**
 * alertPmStartTime
 * Runs every 15 minutes via Cloud Scheduler.
 *
 * A preventive work order created with a scheduled start (the PM flow in the
 * Work Order drawer) has no other trigger when that time arrives. Once the
 * start time has been reached and the PM hasn't been started, the supervisor
 * in charge and the assigned team members get an in-app + push alert. Each WO
 * is alerted once (`pmStartAlertSentAt`).
 *
 * WOs generated by a recurring schedule (schedulePmCheck) are alerted when
 * they are created and are stamped so this job skips them.
 */

const {onSchedule} = require("firebase-functions/v2/scheduler");
const {getFirestore, FieldValue, Timestamp} = require("firebase-admin/firestore");
const {getMessaging} = require("firebase-admin/messaging");
const logger = require("firebase-functions/logger");

const db = getFirestore("default");

// Only a PM nobody has started yet needs the "time to start" nudge.
const NOT_STARTED = ["OPEN", "ASSIGNED"];
// Look back a day so a missed run (or a deploy gap) still alerts, without
// replaying old history.
const LOOKBACK_MS = 24 * 60 * 60 * 1000;

/**
 * @param {object} wo a work order's data
 * @return {string[]} the supervisor in charge and assigned technicians
 */
function pmAlertRecipients(wo) {
  return [...new Set([wo.supervisorInChargeId, ...(wo.assignedTechnicianIds || [])].filter(Boolean))];
}

async function pushToUsers(userIds, title, body, data) {
  const tokens = [];
  for (const uid of userIds) {
    const userDoc = await db.collection("users").doc(uid).get();
    const token = userDoc.exists ? userDoc.data().fcmToken : null;
    if (token) tokens.push(token);
  }
  if (!tokens.length) return;
  try {
    await getMessaging().sendEachForMulticast({tokens, notification: {title, body}, data});
  } catch (err) {
    logger.error("PM start push failed", err);
  }
}

exports.pmAlertRecipients = pmAlertRecipients;

exports.alertPmStartTime = onSchedule({schedule: "*/15 * * * *", timeZone: "Asia/Colombo"}, async () => {
  const now = Date.now();
  try {
    const snap = await db.collection("workOrders")
        .where("woType", "==", "PREVENTIVE")
        .where("scheduledStart", ">=", Timestamp.fromMillis(now - LOOKBACK_MS))
        .where("scheduledStart", "<=", Timestamp.fromMillis(now))
        .get();

    let alerted = 0;
    for (const docSnap of snap.docs) {
      const wo = docSnap.data();
      if (wo.pmStartAlertSentAt || !NOT_STARTED.includes(wo.status)) continue;
      const userIds = pmAlertRecipients(wo);
      const companyId = wo.companyId || wo.siteId;
      if (!companyId) continue;
      try {
        const label = wo.woNumber || (wo.description || "").slice(0, 60) || "Preventive maintenance";
        await db.collection("notifications").add({
          companyId,
          type: "pm",
          message: `PM time reached: "${label}" on ${wo.machineName || "a machine"} is scheduled to start now`,
          oversightMessage: `PM scheduled to start now: "${label}" on ${wo.machineName || "a machine"}`,
          severity: "medium",
          linkTo: `/app/work-orders?woId=${docSnap.id}`,
          timestamp: FieldValue.serverTimestamp(),
          read: false,
          readBy: [],
          recipientRoles: userIds.length ? [] : ["supervisor", "technician"],
          recipientUserIds: userIds,
          targetRoles: userIds.length ? [] : ["supervisor", "technician"],
          targetUserIds: userIds,
          actorName: null,
          actorRole: null,
          actorUserId: null,
          plantId: wo.machinePlantId || null,
          department: wo.machineDepartment || null,
        });
        await pushToUsers(userIds, "PM time reached", `${label} — ${wo.machineName || ""}`,
            {woId: docSnap.id, screen: "WODetail"});
        await docSnap.ref.update({pmStartAlertSentAt: FieldValue.serverTimestamp()});
        alerted++;
      } catch (err) {
        logger.error(`PM start alert failed for ${docSnap.id}`, err);
      }
    }
    logger.info(`alertPmStartTime: ${alerted} PM start alerts sent`);
  } catch (err) {
    logger.error("alertPmStartTime failed", err);
  }
});
